input.oldString:
// Player configuration
  const player = {
    width: 30,
    height: 15,
    x: canvas.width / 2,
    y: canvas.height - 30,
    speed: 5,
    moveLeft: false,
    moveRight: false,
    draw() {
      ctx.fillStyle = '#0f0';
      ctx.fillRect(this.x - this.width / 2, this.y, this.width, this.height);
    },
    update() {
      if (this.moveLeft) this.x -= this.speed;
      if (this.moveRight) this.x += this.speed;
      // Keep within bounds
      const half = this.width / 2;
      this.x = Math.max(half, Math.min(canvas.width - half, this.x));
    }
  };

input.newString:
// Player configuration – spaceship triangle
  const player = {
    width: 30,
    height: 15,
    x: canvas.width / 2,
    y: canvas.height - 30,
    speed: 5,
    moveLeft: false,
    moveRight: false,
    draw() {
      ctx.fillStyle = '#0ff'; // cyan ship
      ctx.beginPath();
      ctx.moveTo(this.x, this.y);
      ctx.lineTo(this.x - this.width / 2, this.y + this.height);
      ctx.lineTo(this.x + this.width / 2, this.y + this.height);
      ctx.closePath();
      ctx.fill();
    },
    update() {
      if (this.moveLeft) this.x -= this.speed;
      if (this.moveRight) this.x += this.speed;
      // Keep within bounds
      const half = this.width / 2;
      this.x = Math.max(half, Math.min(canvas.width - half, this.x));
    }
  };

